class Solution {
    private long cost(long target,int n,long sum,long minimum,int cost1,int cost2){
        long total=target*n-sum,maxDeficit=target-minimum;
        long pairs=Math.min(total/2,total-maxDeficit);
        return pairs*cost2+(total-2*pairs)*cost1;
    }
    public int minCostToEqualizeArray(int[] nums,int cost1,int cost2){
        long sum=0,minimum=Long.MAX_VALUE,maximum=0;
        for(int value:nums){
            sum+=value;
            minimum=Math.min(minimum,value);
            maximum=Math.max(maximum,value);
        }
        long mod=1000000007L,n=nums.length;
        if(n<=2||2L*cost1<=cost2)return (int)(((maximum*n-sum)*cost1)%mod);
        long balance=(sum-2*minimum+n-3)/(n-2),best=Long.MAX_VALUE;
        for(int delta=0;delta<=3;delta++)best=Math.min(best,cost(maximum+delta,nums.length,sum,minimum,cost1,cost2));
        for(int delta=-3;delta<=3;delta++){
            long target=balance+delta;
            if(target>=maximum)best=Math.min(best,cost(target,nums.length,sum,minimum,cost1,cost2));
        }
        return (int)(best%mod);
    }
}

